			text = [=[在腐烂之痕的北部边缘有一座祭坛，一位年老的{link:humans}人类{/link}术士，{link:daio-the-decrepit}衰老的戴奥{/link}，在恶魔之中安了家。寻找他的人是来学习如何束缚一个末日守卫的。]=],
		},
	},
})

Translate("zhCN", "lord-kazzak", {
