Translate("zhCN", "kum-isha-the-collector", {
	title = "收藏家库米沙",
	subtitle = "德莱尼水晶的寻觅者",
	found = "荒原中，污染者高地附近",
	hint = "寻找那位在荒原中心收集水晶的流亡者。",
	allegiance = "迷失的德莱尼",
	aliases = { "库米沙" },
	sections = {
		{
			title = "概述",
			text = [=[收藏家库米沙是在{link:blasted-lands}诅咒之地{/link}游荡的迷失德莱尼之一，一个来自{link:dark-portal}黑暗之门{/link}彼端世界的古老民族的流亡者。他在荒原中心扎营，收集德莱尼水晶，一种来自他故乡的水晶，至今仍能在红色土地中找到。他相信，只要有足够多的这种水晶，他就能打开一道裂隙，带领他的族人回家。]=],
		},
		{
			title = "意义",
			text = [=[库米沙尖刻、骄傲，说话毫不留情。他说，{link:humans}人类{/link}和{link:orcs}兽人{/link}都抱怨对方身上的臭味，但在他的鼻子闻来，这个世界的所有民族气味都一样，他从他们身上闻到的是贪婪。他说，贪婪让他失去了家园，而贪婪也将为他的归途买单。他把自己的珍宝慷慨地交换给给他带来水晶的人，同时又鄙视他们接受了这笔交易。]=],
		},
		{
			title = "事迹",
			text = [=[• 他在{link:blasted-lands}诅咒之地{/link}搜寻德莱尼水晶，最重要的是稀有的无瑕之球。
• 他曾尝试打开一道通往故乡的裂隙。
• 他为送来的每一块水晶碎片付钱，同时轻蔑那些送来水晶的人。]=],
		},
		{
			title = "未载之事",
			text = [=[没有任何编年史记载库米沙和他的同伴是如何来到{link:blasted-lands}诅咒之地{/link}的，也没有记载他们在那里游荡了多久。]=],
		},
	},
	chapters = {
		{
			title = "无瑕之球",
			hint = "把荒原中最稀有的水晶带给收货人。",
			text = [=[库米沙说，德莱尼曾穷尽一生寻找一颗无瑕的德莱尼水晶之球，至死都未能如愿。当一颗被放到他手中时，他简直不敢相信。他立刻试图召唤一道回家的传送门。尝试失败了。他没有失去希望。他又要了一颗。]=],
		},
		{
			title = "一个德莱尼的垃圾",
			hint = "把较次的水晶碎片带给收货人。",
			text = [=[有瑕疵的德莱尼水晶碎片永远打不开回家的路。然而库米沙还是收下它们，因为它们或许能以其他方式为他的族人所用，他用这个世界的珍宝来支付，而他把那些珍宝称为垃圾。他一天要对每个卖家把同样轻蔑的话说上许多遍。他承认他厌恶这个世界。]=],
		},
	},
	mentions = {
		{ text = "为库米沙效力" },
		{ text = "库米沙的努力" },
		{ text = "积少成多" },
		{ text = "一个德莱尼的垃圾……" },
	},
})

